import{z as B,x as r,o as i,c as d,q as t,j as p,D as e,d as n,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"神圣巧合","description":"","frontmatter":{"title":"神圣巧合","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/divine-coincidence.md","filePath":"econ/divine-coincidence.md","lastUpdated":1791063341000}'),A={name:"econ/divine-coincidence.md"};function s(c,a,_,h,m,u){const E=r("Mermaid");return i(),d("div",null,[a[2]||(a[2]=t('<h1 id="神圣巧合" tabindex="-1">神圣巧合 <a class="header-anchor" href="#神圣巧合" aria-label="Permalink to &quot;神圣巧合&quot;">​</a></h1><div class="epigraph"><p>若唯一的名义摩擦是价格粘性，稳定通胀的政策也稳定福利相关缺口；一旦出现真实工资刚性或成本推动，巧合消失，必须权衡。</p><footer>—— Blanchard and Galí, Real Wage Rigidities and the New Keynesian Model, Journal of Money, Credit and Banking 2007</footer></div><p><a href="/econ/discretion-commitment">上一课</a>在同一损失下给出权变与承诺两条路径。损失里同时罚 \\(\\pi\\) 与 \\(\\tilde{y}\\)，仿佛永远有两项目标。本课的缺口是：在基准 NK（只有 Calvo 价格粘性、没有成本推动）里，两项其实是一个——稳通胀已经稳了福利相关缺口。Blanchard 与 Galí 把这叫做神圣巧合，并指出真实工资刚性会拆掉它。零下限是再下一课的工具约束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NKPC \\(\\pi_t=\\beta\\mathbb{E}_t\\pi_{t+1}+\\kappa\\tilde{y}_t\\) 在没有 markup 冲击时，\\(\\pi=0\\)（或 \\(\\pi=\\pi^*\\)）的路径要求 \\(\\tilde{y}=0\\)。灵活价格配置本身就是有效配置（若补贴已抵消垄断加成），于是福利相关缺口与价格缺口重合。央行只要承诺把通胀钉住，缺口自动为零——不必在损失里「平衡」两项。缺口是：这巧合依赖哪一组假设，政策含义不要被三方程的两个损失项吓住。</p><p><span class="marginnote">「成本推动冲击」翻译成日常话：不是需求太旺把物价拉起来，而是成本先涨——油价跳升、工资上调、原材料涨价把企业边际成本推高，企业被迫提价。这种通胀压下去要靠砍需求，缺口因此被殃及，权衡就是这么来的。</span></p><p>上一课刚说明同一损失下权变与承诺路径不同。巧合成立时，两条路径在目标上重合（都稳 \\(\\pi\\)），差只在过渡；巧合破裂后，两项真正分叉，承诺才变成定量地改善权衡。没有本课，损失函数里的两项会被误读成永远有两个独立工具。</p><p><span class="marginnote">巧合不是「通胀无关紧要」。它是：在所列假设下，通胀是缺口的充分统计。有成本推动时，通胀不再是充分统计，必须权衡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>基准：垄断竞争加成被稳态补贴抵消，唯一扭曲是交错价格。Woodford 的二次福利近似把损失写成 \\(\\pi\\) 与 \\(\\tilde{y}\\) 的加权和，但二者被 NKPC 锁死，最优政策（无论权变还是承诺）都是完全稳定通胀。加入独立的成本推动 \\(u_t\\)（markup、石油、工资加成）后，</p> \\[\\pi_t=\\beta\\mathbb{E}_t\\pi_{t+1}+\\kappa\\tilde{y}_t+u_t, \\]<p>\\(\\pi=0\\) 不再蕴含 \\(\\tilde{y}=0\\)。Blanchard–Galí 的真实工资刚性提供微观：工资不能随效率立刻调整，自然产出与有效产出分开，即使没有外生 \\(u_t\\)，稳定价格也不再稳定福利缺口。</p><p><span class="marginnote">数字实例：设 \\(\\kappa=0.1\\)。无成本推动时令 \\(\\pi=0\\)，NKPC 自动给出 \\(\\tilde{y}=0\\)，两个目标一次完成。来了 \\(u_t=1\\) 的成本推动后，硬压 \\(\\pi=0\\) 意味着 \\(\\tilde{y}=-u_t/\\kappa=-10\\)——产出缺口要吃 10 个百分点的紧缩。\\(\\kappa\\) 越小（价格越粘），同一冲击要求的牺牲越大。</span></p>',13)),(i(),p(o,null,{default:e(()=>[l(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E9%9C%80%E6%B1%82%E6%88%96%E6%8A%80%E6%9C%AF%E5%86%B2%E5%87%BB%22%5D%20--%3E%20K1%5B%22NKPC%20%E6%97%A0%E6%AE%8B%E5%B7%AE%3A%20pi%20%E4%B8%8E%E7%BC%BA%E5%8F%A3%E9%94%81%E5%9C%A8%E4%B8%80%E8%B5%B7%22%5D%0A%20%20K1%20--%3E%20ST%5B%22%E7%A8%B3%20pi%20%E5%90%8C%E6%97%B6%E7%A8%B3%E7%BC%BA%E5%8F%A3%3A%20%E5%B7%A7%E5%90%88%E6%88%90%E7%AB%8B%22%5D%0A%20%20S2%5B%22%E6%88%90%E6%9C%AC%E6%8E%A8%E5%8A%A8%E5%86%B2%E5%87%BB%20u_t%22%5D%20--%3E%20K2%5B%22NKPC%20%E5%A4%9A%E5%87%BA%E4%B8%80%E9%A1%B9%3A%20pi%20%E4%B8%8E%E7%BC%BA%E5%8F%A3%E8%84%B1%E9%92%A9%22%5D%0A%20%20K2%20--%3E%20TR%5B%22%E5%8E%8B%20pi%20%E8%A6%81%E7%89%BA%E7%89%B2%E7%BC%BA%E5%8F%A3%3A%20%E5%BF%85%E9%A1%BB%E6%9D%83%E8%A1%A1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),(i(),p(o,null,{default:e(()=>[l(E,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E4%BB%85%E4%BB%B7%E6%A0%BC%E7%B2%98%E6%80%A7%22%5D%20--%3E%20DC%5B%22%E7%A5%9E%E5%9C%A3%E5%B7%A7%E5%90%88%EF%BC%9A%E7%A8%B3%20%CF%80%20%E2%87%92%20%E7%A8%B3%20%E1%BB%B9%22%5D%0A%20%20CP%5B%22%E6%88%90%E6%9C%AC%E6%8E%A8%E5%8A%A8%20%2F%20%E5%B7%A5%E8%B5%84%E5%88%9A%E6%80%A7%22%5D%20--%3E%20TRADE%5B%22%E5%BF%85%E9%A1%BB%E5%9C%A8%20%CF%80%20%E4%B8%8E%E7%BC%BA%E5%8F%A3%E9%97%B4%E6%9D%83%E8%A1%A1%22%5D%0A%20%20COMM%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%E6%89%BF%E8%AF%BA%22%5D%20--%3E%20BOTH%5B%22%E6%94%B9%E5%8F%98%E7%9A%84%E6%98%AF%E6%9D%83%E8%A1%A1%E7%9A%84%E5%BD%A2%E7%8A%B6%22%5D%0A%20%20TRADE%20--%3E%20COMM%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>权变与承诺在巧合成立时都选零通胀；巧合破裂后，二者的路径差才重新变成定量问题——承诺仍更擅长用历史依赖改善权衡，但不能同时把两项钉在零。</p><h3 id="不要把两项损失读成两项独立工具" tabindex="-1">不要把两项损失读成两项独立工具 <a class="header-anchor" href="#不要把两项损失读成两项独立工具" aria-label="Permalink to &quot;不要把两项损失读成两项独立工具&quot;">​</a></h3><p>泰勒规则里同时写 \\(\\phi_\\pi\\) 与 \\(\\phi_y\\)，容易让人以为永远要「兼顾」。巧合成立时，\\(\\phi_y\\) 的角色是识别：技术冲击不应当被当成需求来打。巧合破裂时，\\(\\phi_y\\) 才真正是第二目标的反应。卢卡斯批判：用含 \\(u_t\\) 的样本估出的替换，不能拿到无 \\(u_t\\) 的规则下去当菜单。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>价格粘性造成相对价格错位；通胀是错位的加总。关掉通胀等于关掉错位，缺口回到有效。真实工资刚性把劳动市场的错位加进来：即使价格通胀为零，就业仍可偏离有效。供给冲击让边际成本与需求缺口脱钩，NKPC 的残差就是脱钩。长期中性仍在：无论巧合是否成立，\\(y\\) 回自然路径，\\(\\pi\\) 由名义锚决定；权衡只存在于短局。</p><p>权变与承诺在巧合破裂后差在如何分摊 \\(u_t\\)：承诺用未来一段偏低的 \\(\\pi\\) 换今天较小的双偏离；权变没有这笔账。巧合成立时这笔账是空的——两项本来锁死。因此「要不要承诺」的定量重要性，本身取决于巧合是否还在。开放经济的汇率错位、金融摩擦的利差，是后课才能并列的额外缺口，本课不提前写成新的神圣巧合。</p><p><span class="marginnote">开放经济的汇率错位、金融摩擦的利差，也会制造类似的额外缺口。本课只取 Blanchard–Galí 的工资刚性与成本推动，作为「巧合会破」的最小装置。</span></p><p><span class="marginnote">直觉类比：巧合像体温计——若发烧的唯一原因是感染程度，退烧就是治病；但若发烧还可能来自中暑（成本推动），只顾退烧不等于治病，甚至掩盖病情。「神圣」指的正是这种好运：一个仪表（通胀）恰好代理了唯一的病灶（缺口），而这种好运是可以被真实世界的摩擦取消的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计牺牲比，不把巧合写成「因此只看通胀」的政治口号——那要先检验 \\(u_t\\) 与工资刚性是否可忽略。量化栏没有宏观权衡。也不在这里展开工资菲利普斯的全套校准。稳态垄断加成若未被补贴抵消，灵活价格配置本身已不是有效配置，巧合在定义上就要重写福利缺口；Woodford 的近似通常先把这项用补贴拿掉，本课跟随，不把一次总付补贴当现实税制。</p><p>下限上即使巧合在正利率区成立，工具卡住也会强迫一项偏离——那是工具约束，不是又一个成本推动。本课先在可以执行 \\(\\phi_\\pi\\gt 1\\) 的区域把巧合钉死。</p><p>后课默认：基准 NK 可以有神圣巧合；有成本推动或真实刚性则必须权衡。下一课：规则给出的 \\(i\\) 碰到有效下限，承诺必须换工具或换路径语言。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>仅价格粘性、无成本推动时，稳通胀即稳福利缺口。</li><li>markup 冲击或真实工资刚性拆掉巧合。</li><li>损失里两项在巧合下不是两个独立目标。</li><li>承诺改善权衡形状，不恢复巧合本身。</li><li>开放汇率错位与金融利差是后课才能并列的额外缺口。</li><li>出处：Blanchard and Galí, <em>JMCB</em> 2007；对照 Woodford 的福利近似。</li></ul>',14))])}const D=B(A,[["render",s]]);export{f as __pageData,D as default};
